// Basemaps (SPEC §7.2, §7.7).
//
// * Offline basemap of cached cells: Protomaps "grayscale" layers, generated by
//   tools/build_basemap_style.mjs with local place names.  The source can only
//   have one max zoom; the backend reports the lowest max zoom of the cached
//   cells, and the map over-zooms above it.
// * Online basemap elsewhere: OpenFreeMap "Positron" recoloured to the same
//   palette (tools/build_online_style.py); its source is added in layers.js.
//
// Below z8 the offline basemap's tiles (z0-z7, shared by many cells) reach far
// beyond the cached cells, so while the online basemap works it is used
// everywhere at those zooms, and the offline one only from z8 on; offline, the
// offline basemap is shown at every zoom.
import { url } from './api.js';
import { addToGroup } from './layers.js';

const OFFLINE_FROM_ZOOM_ONLINE = 8;

let layers = [];
let onlineLayers = [];
let version = 1;
let maxzoom = null;
let onlineMode = true;

export async function loadBasemapStyles() {
  const [offline, online] = await Promise.all([
    fetch(url('/app/vendor/basemap/grayscale-layers.json')).then((r) => r.json()),
    fetch(url('/app/vendor/basemap/online-layers.json')).then((r) => r.json()),
  ]);
  layers = offline;
  onlineLayers = online;
}

export function onlineBasemapLayers() {
  return onlineLayers;
}

const tiles = () => [url(`/tiles/basemap/{z}/{x}/{y}.mvt?v=${version}`)];

function layerMinzoom(layer) {
  return Math.max(layer.minzoom || 0, onlineMode ? OFFLINE_FROM_ZOOM_ONLINE : 0);
}

export function addBasemap(map, zoom) {
  maxzoom = zoom;
  map.addSource('basemap', { type: 'vector', tiles: tiles(), minzoom: 0, maxzoom: zoom });
  for (const layer of layers) addToGroup(map, 'basemap', { ...layer, minzoom: layerMinzoom(layer) });
}

export function setBasemapMaxzoom(map, zoom) {
  if (zoom === maxzoom || !map.getSource('basemap')) return;
  for (const layer of layers) if (map.getLayer(layer.id)) map.removeLayer(layer.id);
  map.removeSource('basemap');
  addBasemap(map, zoom);
}

/** True while the online basemap can be used (network up, OpenFreeMap not paused). */
export function onlineBasemapUsable(status) {
  if (!status || status.network === 'offline') return false;
  const service = (status.services || {}).ofm;
  return !service || service.state === 'ok';
}

export function setBasemapMode(map, online) {
  if (online === onlineMode) return;
  onlineMode = online;
  for (const layer of layers) {
    if (map.getLayer(layer.id)) map.setLayerZoomRange(layer.id, layerMinzoom(layer), layer.maxzoom ?? 24);
  }
}

export function refreshBasemap(map, newVersion) {
  version = newVersion;
  const source = map.getSource('basemap');
  if (source) source.setTiles(tiles());
}
